def tool(text):
    import re
    # Match typical German case numbers like "Az. 1 BvR 123/23" or "VG Hamburg 2 S 45/2022"
    pattern = r"(?:Az\.?\s*)?\d+\s*[A-Za-z]{1,3}\s*\d{1,4}/\d{2,4}"  # simple heuristic
    matches = re.findall(pattern, text)
    return ", ".join(matches)

