def tool(text):
    numbers = []
    # Extract integers, handling commas/hyphens
    for match in re.finditer(r'\d{1,3}(?:,\d{3})*(?:-\d{1,3}(?:,\d{3})*)?', text):
        num = match.group().replace(',', '').replace('-', ' ')
        numbers.extend(int(n) for n in num.split() if n.isdigit())
    return ','.join(map(str, numbers))

