    counts = re.findall(r'\b(?:about|approx|around|~|\+|-|between|up to|over|under|\d{1,3}(?:,\d{3})*(?:\s*[+-]\s*\d{1,3}(?:,\d{3})*)?)\s*(?:deaths?|fatalities?|casualties?|injured|affected)\b', text, re.IGNORECASE)
